<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
$from = trim($_GET['debut'] ?? ''); $to = trim($_GET['fin'] ?? ''); $type = strtoupper(trim($_GET['type'] ?? ''));
$validDate = static function (string $value): bool { if ($value === '') return true; $d = DateTimeImmutable::createFromFormat('!Y-m-d', $value); return $d && $d->format('Y-m-d') === $value; };
if (!$validDate($from) || !$validDate($to) || ($from !== '' && $to !== '' && $from > $to) || !in_array($type, ['', 'N', 'P', 'S', 'R'], true)) { http_response_code(422); exit('Filtres invalides.'); }
$sql = 'SELECT a.idAction, a.titreAction, a.typeAction, a.dateAction, a.lieu, m.nom FROM action a INNER JOIN membre m ON m.mail = a.mail WHERE (? = \'\' OR a.dateAction >= ?) AND (? = \'\' OR a.dateAction <= ?) AND (? = \'\' OR a.typeAction = ?) ORDER BY a.dateAction, a.idAction';
$stmt = $con->prepare($sql); $stmt->bind_param('ssssss', $from, $from, $to, $to, $type, $type); $stmt->execute(); $actions = $stmt->get_result();
$types = ['N'=>'Nettoyage','P'=>'Plantation','S'=>'Sensibilisation','R'=>'Recyclage'];
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Liste des actions — EcoJeunes</title><link rel="stylesheet" href="mesStyles1.css"></head><body><main class="container"><p><a href="index.html">← Accueil</a></p><h1>Actions environnementales</h1><form method="get" action="liste.php" class="filters"><label for="debut">À partir du</label><input type="date" id="debut" name="debut" value="<?= h($from) ?>"><label for="fin">Jusqu'au</label><input type="date" id="fin" name="fin" value="<?= h($to) ?>"><label for="type">Type d'action</label><select id="type" name="type"><option value="">Tous les types</option><?php foreach ($types as $key=>$label): ?><option value="<?= h($key) ?>" <?= $type === $key ? 'selected' : '' ?>><?= h($label) ?></option><?php endforeach; ?></select><button type="submit">Filtrer</button><a href="liste.php">Effacer</a></form>
<?php if ($actions->num_rows === 0): ?><p>Aucune action ne correspond à ces filtres.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Action</th><th>Type</th><th>Date</th><th>Lieu</th><th>Proposée par</th></tr></thead><tbody><?php while ($row = $actions->fetch_assoc()): ?><tr><td><?= h($row['titreAction']) ?></td><td><?= h($types[$row['typeAction']] ?? 'Autre') ?></td><td><?= h($row['dateAction']) ?></td><td><?= h($row['lieu']) ?></td><td><?= h($row['nom'] ?? '') ?></td></tr><?php endwhile; ?></tbody></table></div><?php endif; ?></main></body></html>
